import java.util.Arrays;
import java.util.stream.IntStream;

public class Sumatorias {
  public static void main(String[] args) {
      int[] arr1 = {1, 2, 3};
      int[] arr2 = {1, 2, 3};

      // En Java Moderno (Java 8+) el equivalente a np.sum() es un Stream de reducción
      int total1 = IntStream.of(arr1).sum();
      int total2 = IntStream.of(arr2).sum();

      System.out.println(total1 + total2); // 12
  }
}
